from pathlib import Path

import pandas as pd


LOG_PATH = Path("monitoring/predictions.csv")


def load_predictions():
    """Load prediction logs generated by the fraud API."""

    if not LOG_PATH.exists():
        raise FileNotFoundError(
            f"Prediction log not found: {LOG_PATH}. "
            "Send some requests to the /predict endpoint first."
        )

    return pd.read_csv(LOG_PATH)


def generate_monitoring_report(df):
    """Calculate basic production prediction metrics."""

    total_predictions = len(df)

    review_count = (df["decision"] == "REVIEW").sum()
    approve_count = (df["decision"] == "APPROVE").sum()

    review_rate = (
        review_count / total_predictions
        if total_predictions > 0
        else 0.0
    )

    average_fraud_probability = df["fraud_probability"].mean()
    df["logged_at"] = pd.to_datetime(df["logged_at"], utc=True)

    latest_time = df["logged_at"].max()
    recent_cutoff = latest_time - pd.Timedelta(hours=1)

    recent_df = df[df["logged_at"] >= recent_cutoff]

    recent_predictions = len(recent_df)

    recent_review_count = (
        recent_df["decision"] == "REVIEW"
    ).sum()

    recent_review_rate = (
        recent_review_count / recent_predictions
        if recent_predictions > 0
        else 0.0
    )
    

    return {
        "total_predictions": int(total_predictions),
        "approve_count": int(approve_count),
        "review_count": int(review_count),
        "review_rate": float(review_rate),
        "average_fraud_probability": float(
            average_fraud_probability
        ),
        "recent_predictions_1h": int(recent_predictions),
        "recent_review_rate_1h": float(recent_review_rate),
    }


def main():
    df = load_predictions()
    report = generate_monitoring_report(df)

    print("=" * 60)
    print("FRAUD MODEL MONITORING REPORT")
    print("=" * 60)

    print(f"Total predictions:          {report['total_predictions']}")
    print(f"Approved transactions:      {report['approve_count']}")
    print(f"Transactions for review:    {report['review_count']}")
    print(f"Review rate:                 {report['review_rate']:.2%}")
    print(
        "Average fraud probability: "
        f"{report['average_fraud_probability']:.4f}"
    )
    print(
    f"Predictions in last 1 hour: {report['recent_predictions_1h']}"
    )
    print(
        f"Recent review rate:         {report['recent_review_rate_1h']:.2%}"
    )

    print("=" * 60)


if __name__ == "__main__":
    main()